    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        grid = message.message[0].data[1]
        prev_move = message.message[0].data[0]
        move = None

        def is_valid_move(grid, row, col, num):
            for i in range(len(grid)):
                if grid[row][i] == num:
                    return False
            for i in range(len(grid)):
                if grid[i][col] == num:
                    return False
            subgrid_size = int(len(grid) ** 0.5)
            start_row, start_col = row - row % subgrid_size, col - col % subgrid_size
            for i in range(subgrid_size):
                for j in range(subgrid_size):
                    if grid[i + start_row][j + start_col] == num:
                        return False
            return True

        def find_move(grid, prev_move):
            if prev_move is None:
                for i in range(len(grid)):
                    for j in range(len(grid)):
                        if grid[i][j] == 0:
                            for num in range(1, len(grid) + 1):
                                if is_valid_move(grid, i, j, num):
                                    return [(i, j), num]
            else:
                row, col = prev_move[0]
                for i in range(len(grid)):
                    if grid[row][i] == 0:
                        for num in range(1, len(grid) + 1):
                            if is_valid_move(grid, row, i, num):
                                return [(row, i), num]
                for i in range(len(grid)):
                    if grid[i][col] == 0:
                        for num in range(1, len(grid) + 1):
                            if is_valid_move(grid, i, col, num):
                                return [(i, col), num]
                for i in range(len(grid)):
                    for j in range(len(grid)):
                        if grid[i][j] == 0:
                            for num in range(1, len(grid) + 1):
                                if is_valid_move(grid, i, j, num):
                                    return [(i, j), num]
            return None

        move = find_move(grid, prev_move)

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=move, type='custom')]
        )
